const b = $json.body || $json;
const rawFrom = (b.From || b.from || '').toString();
const phone = rawFrom.replace(/^whatsapp:/i, '').replace(/[\s\-()]/g, '').trim();
let message = (b.Body || b.body || '').toString().trim();
const sid = (b.MessageSid || b.SmsMessageSid || b.SmsSid || '').toString();

// MEDIA (2026-08-21) - see the router's copy of this parser for the full story.
// A WhatsApp voice note arrives with an EMPTY Body and NumMedia>=1. Treating that
// as 'no message' dropped it silently: no reply, no conversations row, and the 48h
// silence clock kept running, so a lead who HAD answered was closed for not answering.
const numMedia = parseInt((b.NumMedia || b.numMedia || '0').toString(), 10) || 0;
const mediaType = (b.MediaContentType0 || '').toString().toLowerCase();
const hasMedia = numMedia > 0;
let mediaKind = null;
if (hasMedia) {
  if (mediaType.indexOf('audio') === 0) mediaKind = 'voice';
  else if (mediaType.indexOf('image') === 0) mediaKind = 'image';
  else if (mediaType.indexOf('video') === 0) mediaKind = 'video';
  else if (mediaType.indexOf('application/pdf') === 0) mediaKind = 'document';
  else mediaKind = 'attachment';
  if (!message) {
    const label = { voice: '[voice note]', image: '[image]', video: '[video]', document: '[document]', attachment: '[attachment]' };
    message = label[mediaKind];
  }
}

const skip = (!phone || !message);
return [{ json: {
  inbound_phone: phone,
  inbound_message: message,
  inbound_sid: sid,
  has_media: hasMedia,
  media_kind: mediaKind,
  media_type: mediaType || null,
  num_media: numMedia,
  skip: skip
} }];

function tryNode(name){ try { const it = $(name).item; return it ? it.json : null; } catch (e) { return null; } }
let row = null;
const q = tryNode('Lookup Qualifying Lead');
const qHas = !!(q && Array.isArray(q.body) && q.body.length);
if (qHas) row = q.body[0];
if (!row) { const r = tryNode('Reopen Lead'); if (r && Array.isArray(r.body) && r.body.length) row = r.body[0]; }
if (!row) { throw new Error('Resolve Lead Context: no lead row resolved from either lookup'); }
const phone = $('Parse Inbound Message').item.json.inbound_phone;
return [{ json: {
  lead_id: row.id,
  whatsapp_number: row.whatsapp_number || phone,
  language: row.language || 'en',
  country_code: row.country_code || null,
  property_interest: row.property_interest || null,
  buyer_or_seller: row.buyer_or_seller || null,
  area_of_interest: row.area_of_interest || null,
  budget_min: (row.budget_min === undefined ? null : row.budget_min),
  budget_max: (row.budget_max === undefined ? null : row.budget_max),
  currency: row.currency || null,
  timeline: row.timeline || null,
  reengaged: !qHas
} }];

const ctx = $('Resolve Lead Context').item.json;
const hist = ($('Load Conversation History').item.json.body) || [];
const inboundMsg = $('Parse Inbound Message').item.json.inbound_message;

const system = [
 'You are the qualification assistant for a MENA real-estate agency, talking to a lead over WhatsApp. You continue an ongoing conversation: you get the full message history and the lead newest message. Gather the few facts an agent needs, decide what happens next, and write the single next message.',
 'LANGUAGE: reply in the language the lead is using RIGHT NOW (ar | en | fr | mixed). If they switch language mid-conversation, follow them, never force them back. ar = natural Arabic in the country register (Gulf/Levant/Egyptian). mixed = lead in Arabic, light English ok.',
 'CULTURAL (non-negotiable): formality by tone - casual/short/emoji => informal Arabic anta (أنت); formal/business/older => respectful hadretak (حضرتك); unsure => lean respectful. NEVER use in-sha-Allah (إن شاء الله) for logistics/timing, use we will do our best (سنبذل قصارى جهدنا). No faith-assuming greeting (neutral marhaba / Hello / Bonjour). Currency NEVER assumed.',
 'NEVER ANSWER WHAT YOU CANNOT KNOW: you have NO access to prices, availability, specific units or listings, commission, agency fees, payment plans, service charges, ROI or rental yields, mortgage, visa, residency, tax or legal rules, or anything about the agency commercial terms. If the lead asks about any of these, say plainly and briefly that you cannot confirm it and the specialist will. Do NOT estimate, do NOT answer with "typically", "usually", "around", "standard", "market rate" or any range, and do NOT describe what is normal in the market. Inventing a number or a norm here is worse than saying you do not know. After saying so, continue with your own outstanding question.',\n 'ACKNOWLEDGEMENTS ARE NOT PROGRESS: a bare "ok", "thanks", "sure", "tmam" or an emoji-only reply carries NO new information and is never a reason to hand off. Use action="continue" and re-ask the outstanding question, rephrased more concretely than last time.',\n 'HANDOFF IS FINAL: if action="handoff", next_message must be a CLOSING statement and must NOT contain a question. Once you hand off, a human owns the conversation and the assistant stops replying - so any question you ask there will never be answered. If you still need one more fact, use action="continue" and ask for it instead of handing off.',\n 'MEDIA: a message shown as [voice note], [image], [video], [document] or [attachment] means the lead sent that INSTEAD of text. You cannot hear audio or open files. NEVER pretend you did and never guess the contents. Reply warmly in their language, say plainly that you could not open it, and ask them to type the key detail instead. Keep action=continue unless they are clearly opting out.',\n 'EXTRACT only what the lead actually said, else null: budget_min, budget_max (numbers; single figure => budget_max only; range => both); currency (AED,SAR,USD,LBP,EGP,QAR,KWD,MAD,TND,DZD; null if unstated); timeline (short text as stated); buyer_or_seller (buyer/seller if clear); area_of_interest.',
 'DECIDE action: handoff = enough for an agent (area AND (budget OR firm timeline)) OR clearly high-intent/ready OR the lead asks for a human. end = lead opts out / not interested / wrong number / asks to stop. continue = otherwise, ask the single most useful missing fact.',
 'next_message: ONE WhatsApp message under 500 chars in the lead current language. continue => ask exactly ONE question for the most valuable missing field. handoff => warm handoff, a specialist will follow up shortly (no specific time, no إن شاء الله). end => brief polite close, no hard sell. Concrete, respectful, no dream-home hype, at most one tasteful emoji if it matches the lead tone.',
 'OUTPUT ONLY a JSON object, no prose, no code fences: {"extracted_info":{"budget_min":number|null,"budget_max":number|null,"currency":string|null,"timeline":string|null,"buyer_or_seller":"buyer"|"seller"|null,"area_of_interest":string|null},"action":"continue"|"handoff"|"end","next_message":string,"language_used":"ar"|"en"|"fr"|"mixed"}'
].join('\n');

const header = [
 'Lead context (already known, do not re-ask what is already filled):',
 '- language (last known): ' + (ctx.language || ''),
 '- country: ' + (ctx.country_code || ''),
 '- property_interest: ' + (ctx.property_interest || ''),
 '- buyer_or_seller: ' + (ctx.buyer_or_seller || ''),
 '- area_of_interest: ' + (ctx.area_of_interest || ''),
 '- budget_min: ' + (ctx.budget_min == null ? '' : ctx.budget_min) + ' / budget_max: ' + (ctx.budget_max == null ? '' : ctx.budget_max) + ' / currency: ' + (ctx.currency || ''),
 '- timeline: ' + (ctx.timeline || ''),
 '',
 'The lead reached out about: ' + (ctx.property_interest || 'a property') + '. Continue the conversation.'
].join('\n');

const raw = [];
raw.push({ role: 'user', content: header });
hist.forEach(function(r){ raw.push({ role: (r.direction === 'outbound' ? 'assistant' : 'user'), content: (r.message || '').toString() }); });
raw.push({ role: 'user', content: inboundMsg });

const messages = [];
raw.forEach(function(m){
  if (!m.content) return;
  if (messages.length && messages[messages.length - 1].role === m.role) { messages[messages.length - 1].content += '\n\n' + m.content; }
  else { messages.push({ role: m.role, content: m.content }); }
});

const outbound_count = hist.filter(function(r){ return r.direction === 'outbound'; }).length;
const body = { model: 'claude-sonnet-5', max_tokens: 600, thinking: { type: 'disabled' }, system: system, messages: messages };
return [{ json: { anthropic_body: body, outbound_count: outbound_count, _language: ctx.language || 'en' } }];

const built = $('Build Conversation Request').item.json;
const outbound_count = built.outbound_count || 0;
const lang = built._language || 'en';
function extractJson(t){ if (!t) return null; const s = t.indexOf('{'); const e = t.lastIndexOf('}'); if (s < 0 || e < 0 || e < s) return null; try { return JSON.parse(t.slice(s, e + 1)); } catch (err) { return null; } }
let parsed = null; let degraded = true;
try {
  const data = ($json && $json.body) ? $json.body : $json;
  if (data && Array.isArray(data.content)) {
    const tb = data.content.find(function(b){ return b && b.type === 'text' && b.text; });
    if (tb) { parsed = extractJson(tb.text); if (parsed) degraded = false; }
  }
} catch (e) {}
if (!parsed) parsed = { extracted_info: {}, action: 'handoff', next_message: '', language_used: lang };
let action = (['continue', 'handoff', 'end'].indexOf(parsed.action) >= 0) ? parsed.action : 'handoff';
// TRIVIAL ACK GUARD (2026-08-22). A bare "ok" or a thumbs-up carries no new information, but
// the model read "nothing left to extract" as "ready for a human" and handed off - creating a
// cold HubSpot contact and pinging an agent for an emoji. An acknowledgement is not a
// qualification signal, so keep talking. The 6-turn cap below still runs after this and wins,
// so a lead sending nothing but emojis cannot loop forever.
const rawInbound = (function () { try { return ($('Parse Inbound Message').item.json.inbound_message || '').toString(); } catch (e) { return ''; } })();
const ackNorm = rawInbound.toLowerCase().replace(/[\s\p{P}\p{S}]/gu, '');
const ACK_WORDS = ['ok','okay','k','kk','yes','yep','yeah','sure','fine','good','great','thanks','thank','thankyou','ty','tmam','tamam','تمام','اوك','شكرا','ماشي','merci','daccord','oui'];
// Emoji-only survives as an empty string once punctuation and symbols are stripped.
const trivial_ack = (ackNorm === '' && rawInbound.trim() !== '') || (ackNorm.length <= 10 && ACK_WORDS.indexOf(ackNorm) >= 0);
if (trivial_ack && action === 'handoff') { action = 'continue'; }

let capped = false;
if (action === 'continue' && outbound_count >= 6) { action = 'handoff'; capped = true; }
const ei = parsed.extracted_info || {};
const new_status = (action === 'handoff') ? 'qualified' : (action === 'end' ? 'dead' : 'qualifying');
const patch = { status: new_status };
// Re-arm the pre-close nudge (02b): this lead has just spoken, so if they go quiet again
// later they should get a fresh follow-up rather than being closed in silence.
patch.nudged_at = null;
// Always stamp activity. The lead just spoke, so 02b's 48h silence clock must reset even
// on a turn where nothing extractable changed ("hmm", a voice note) - otherwise the patch
// is a no-op and the lead gets closed for not replying. Migration 005 honours an explicit
// updated_at; without it the trigger would ignore this.
patch.updated_at = new Date().toISOString();
function setIf(k, v){ if (v !== null && v !== undefined && v !== '') patch[k] = v; }
setIf('budget_min', ei.budget_min);
setIf('budget_max', ei.budget_max);
setIf('currency', ei.currency);
setIf('timeline', ei.timeline);
setIf('area_of_interest', ei.area_of_interest);
if (ei.buyer_or_seller === 'buyer' || ei.buyer_or_seller === 'seller') patch.buyer_or_seller = ei.buyer_or_seller;
if (['ar', 'en', 'fr', 'mixed'].indexOf(parsed.language_used) >= 0) patch.language = parsed.language_used;
let next_message = (parsed.next_message || '').toString().trim();
if (!next_message) {
  const tmpl = { ar: 'شكراً لتواصلك. سيتواصل معك أحد المختصين قريباً لمتابعة طلبك.', fr: 'Merci pour votre message. Un de nos spécialistes vous recontactera très bientôt.', en: 'Thanks for your message. One of our specialists will follow up with you shortly.' };
  const askTmpl = { ar: 'تمام. لأقدر ساعدك أسرع، ممكن تخبرني الميزانية والعملة اللي بتفكر فيها؟', fr: 'Parfait. Pour avancer, pourriez-vous me preciser votre budget et la devise ?', en: 'Great. To move this forward, could you share your budget range and which currency you are working in?' };
  // A continue must never fall back to the handoff wording, or the lead is told a specialist is
  // coming while the assistant is still asking questions.
  next_message = (action === 'continue') ? (askTmpl[lang] || askTmpl.en) : (tmpl[lang] || tmpl.en);
}
if (next_message.length > 500) next_message = next_message.slice(0, 497) + '…';
return [{ json: { action: action, capped: capped, trivial_ack: trivial_ack, degraded: degraded, new_status: new_status, lead_patch: patch, next_message: next_message, language_used: parsed.language_used || lang, extracted_info: ei, outbound_count: outbound_count } }];
